import java.io.*;
import java.util.*;

public final class CF_630_D2_E_V3 {

    private static final boolean VERBOSE = false;
    private static PrintWriter pw;
    private static FastScanner fs;

    private static void trace(Object... args) {
        if (VERBOSE) {
            for (Object o : args) System.err.print(o + " ");
            System.err.println();
        }
    }

    private static long modPow(long base, long exp, long mod) {
        base %= mod;
        long res = 1;
        for (; exp > 0; exp >>= 1) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
        }
        return res;
    }

    private static void mainLogic() throws IOException {
        pw = new PrintWriter(new BufferedOutputStream(System.out));
        fs = new FastScanner(System.in);

        long n = fs.nextLong();
        long m = fs.nextLong();
        int L = fs.nextInt();
        int R = fs.nextInt();

        long MOD = 998244353L;
        long totalCells = n * m;
        long inv2 = modPow(2, MOD - 2, MOD);

        long diff = R - L + 1;
        long oddNumbers = diff / 2;
        long evenNumbers = diff - oddNumbers;

        long answer;
        if (totalCells % 2 == 1) {
            answer = modPow(diff, totalCells, MOD);
        } else {
            long termA = modPow(diff, totalCells, MOD);
            long termB = modPow(Math.abs(evenNumbers - oddNumbers), totalCells, MOD);
            answer = (termA + termB) % MOD;
            answer = (answer * inv2) % MOD;
        }

        pw.println(answer);
        pw.close();
    }

    public static void main(String[] args) {
        try {
            mainLogic();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class FastScanner {
        private final InputStream is;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            this.is = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = is.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private void skip() throws IOException {
            int c;
            while ((c = read()) <= 32 && c != -1) {}
            ptr--;
        }

        public int nextInt() throws IOException {
            skip();
            boolean neg = false;
            int c = read();
            if (c == '-') {
                neg = true;
                c = read();
            }
            int val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }

        public long nextLong() throws IOException {
            skip();
            boolean neg = false;
            int c = read();
            if (c == '-') {
                neg = true;
                c = read();
            }
            long val = 0;
            while (c >= '0' && c <= '9') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return neg ? -val : val;
        }
    }
}
